 const partial=raw.status!=='COMPLETE'||raw.publication?.status==='CONFIRMED_PARTIAL'||saved!==null&&total!==null&&saved!==total||count(raw.partial_saved_windows)>0||windows.some(row=>row.status!=='SAVED_SETTLED')||unknownRequests>0||unknownWindows>0;
