const reviewLabels={same:'视为同一对象',different:'保留为不同对象',uncertain:'暂不确定',accept:'采用当前定义',reject:'不采用当前定义',unify:'统一到选定定义',keep_separate:'分别保留定义',exclude:'不采用此定义',defer:'暂缓判断',replace:'修订知识内容',revoke:'撤回此前决定'};
