export function lightogPending(s){return lightogTriagePending(s,{heading,control,metadataSources,reviewHistory});}

export function lightogUpload(s){return heading(s.route.library_id?'添加资料':'添加第一份资料','文件保存后自动整理，已取得的正文和知识会陆续开放。')+`<form data-lw-upload-form class="lw-upload-form"><label>知识库名称<input name="library-name" value="${esc(s.view?.library?.name??'')}" ${s.route.library_id?'readonly':''} placeholder="给这个知识空间起个名字"></label><label class="lw-dropzone"><span>＋</span><strong>选择资料</strong><small>PDF、DOCX、Markdown · 每份不超过 20MB</small><input type="file" name="files" multiple accept=".pdf,.docx,.md" required></label><p>上传后会自动整理为知识图谱，无需逐步操作。${!s.models?.generation?.configured?'当前未配置整理模型；资料保存后可先阅读，并在设置中配置模型。':''}</p><button class="lw-button primary" type="submit" ${s.uploading?'disabled':''}>${s.uploading?'正在保存资料…':'上传并自动整理'}</button><p role="status" data-lw-upload-progress>${esc(s.uploadProgress??'')}</p>${s.uploadNotice?`<p class="lw-notice">${esc(s.uploadNotice)}</p>`:''}${s.uploadResult?.uploaded_sources?.length&&s.uploadResult.library_id===s.route.library_id?`<details><summary>已保存原件 · ${s.uploadResult.uploaded_sources.length}</summary>${s.uploadResult.uploaded_sources.map(src=>`<p><a href="/api/documents/${encodeURIComponent(src.document_id)}/original" target="_blank" rel="noopener">${esc(src.title)}</a></p>`).join('')}</details>`:''}</form>`;}
export function lightogLibraries(s){return heading('知识空间','选择知识库，继续查看资料与关联。',control('＋ 新建知识库','new-library','','primary'))+(s.openPg?'<p>'+control('查看 PG 知识空间','pg-libraries')+'</p>':'')+`<div class="lw-libraries">${list(s.boot.knowledge_bases).map(lib=>`<button data-lw-action="library" data-id="${esc(lib.id)}"><span>◈</span><h2>${esc(lib.name)}</h2><p>${lib.source_count??0} 份资料</p><small>打开图谱 →</small></button>`).join('')||empty('建立第一个知识空间','从一份资料开始，逐步整理知识。',control('添加第一份资料','new-library','','primary'))}</div>`;}
export function lightogSettings(s){return heading('设置','连接整理、原文索引与检索模型。')+`<div class="lw-settings">${['generation','embedding','reranker'].map((role,i)=>{const m=s.models?.[role]??{};return `<section><h2>${['整理模型','原文索引模型（可选）','检索重排模型（可选）'][i]}</h2>${tag(m.configured?'已配置':'未配置')}<form data-lw-model-form data-role="${role}"><label>接口地址<input name="url" type="url" value="${esc(m.base_url??MODEL_PRESETS[role].base_url)}" required></label><label>模型名称<input name="model" value="${esc(m.model??MODEL_PRESETS[role].model)}" required></label><label>接口协议<select name="protocol"><option value="openai-compatible" ${(m.protocol??MODEL_PRESETS[role].protocol)==='openai-compatible'?'selected':''}>OpenAI 兼容接口</option>${role!=='generation'?`<option value="dashscope-native" ${(m.protocol??MODEL_PRESETS[role].protocol)==='dashscope-native'?'selected':''}>DashScope 原生接口</option>`:''}</select></label><label>API Key<input name="key" type="password" autocomplete="off" required placeholder="仅用于当前本机服务，不写入页面记录"></label>${role==='embedding'?`<label>向量维度<input name="dimensions" type="number" min="1" max="32768" value="${m.dimensions??1024}"></label>`:''}<button type="submit" class="lw-button">保存模型配置</button></form></section>`;}).join('')}</div>`;}
export function lightogWorkspaceMarkup(s){const pages={graph:lightogGraph,sources:lightogSources,reader:lightogReader,ontology:lightogOntology,pending:lightogPending,query:lightogQuery,upload:lightogUpload,libraries:lightogLibraries,settings:lightogSettings},blocked=['graph','ontology'].includes(s.route.page)&&s.currentMemoryBlocked===true;return lightogWorkspaceShell(s,{mainClass:`lw-page-${s.route.page}`,body:blocked?`<section class="lw-notice" role="alert" data-lw-current-memory-blocked><h1>当前图与知识尚未确认</h1><p>本次读回尚未通过确认或发生失败。原话和资料仍保留，可重新读取。</p>${control('重新读取','refresh-results')}</section>`:s.loading?'<div class="lw-loading" role="status">正在读取知识空间…</div>':`${s.loadError?`<div class="lw-notice">${esc(s.loadError)} ${control('重新读取','refresh-results')}</div>`:''}${(pages[s.route.page]??lightogGraph)(s)}`});}
